// FizzBuzz - print numbers 1 to 100, but "Fizz" for multiples of 3,
// "Buzz" for multiples of 5, "FizzBuzz" for both.

for (var i = 1; i <= 100; i++) {
  if (i % 3 == 0 && i % 5 == 0) {
    console.log("FizzBuzz");
  } else if (i % 3 == 0) {
    console.log("Fizz");
  } else if (i % 5 == 0) {
    console.log("Buzz");
  } else {
    console.log(i);
  }
}

// The I/O lives here. It is deliberately too simple to contain bugs.
import { fizzbuzzRange } from './fizzbuzz.js';

console.log(fizzbuzzRange(1, 100).join('\n'));

// The RULES live here. This file never prints anything — it only decides.

export function fizzbuzz(n) {
  const parts = [];
  if (n % 3 === 0) parts.push('Fizz');
  if (n % 5 === 0) parts.push('Buzz');
  return parts.length > 0 ? parts.join('') : String(n);
}

export function fizzbuzzRange(start, end) {
  const lines = [];
  for (let n = start; n <= end; n++) {
    lines.push(fizzbuzz(n));
  }
  return lines;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fizzbuzz, fizzbuzzRange } from './fizzbuzz.js';

test('plain numbers come back as strings', () => {
  assert.equal(fizzbuzz(1), '1');
  assert.equal(fizzbuzz(7), '7');
});

test('multiples of 3 are Fizz', () => {
  assert.equal(fizzbuzz(3), 'Fizz');
  assert.equal(fizzbuzz(9), 'Fizz');
});

test('multiples of 5 are Buzz', () => {
  assert.equal(fizzbuzz(5), 'Buzz');
  assert.equal(fizzbuzz(20), 'Buzz');
});

test('multiples of both are FizzBuzz', () => {
  assert.equal(fizzbuzz(15), 'FizzBuzz');
  assert.equal(fizzbuzz(45), 'FizzBuzz');
});

test('range produces one entry per number', () => {
  assert.deepEqual(fizzbuzzRange(1, 5), ['1', '2', 'Fizz', '4', 'Buzz']);
});
